      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1020000-0001-4001-8001-000000000001', 'Amburukay', 'Raises Matan-ayon and Saranggaon as her own daughters in a golden chamber as binukot. Makes a vow about her golden pubic hair and marriage.', 'draft') ON CONFLICT (id) DO NOTHING;
