      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1020000-0001-4001-8001-000000000002', 1 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1020000-0001-4001-8001-000000000002');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1020000-0001-4001-8001-000000000003', 'Saranggaon', 'Raised by Amburukay as a binukot in a golden chamber; presented for marriage to Labaw Donggon.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1020000-0001-4001-8001-000000000003', 2 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1020000-0001-4001-8001-000000000003');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1020000-0001-4001-8001-000000000004', 'Labaw Donggon', 'Takes Amburukay''s golden pubic hair after enchanting her to sleep; bound to her marriage condition; judged worthy to marry the daughters she raised.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1020000-0001-4001-8001-000000000004', 3 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1020000-0001-4001-8001-000000000004');
      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1020000-0001-4001-8001-000000000001', ch_id, 'Vows and conditions', 'PENDING CLIENT APPROVAL — The source describes Amburukay''s vow linking marriage to stealing her golden pubic hair, and Labaw Donggon becoming bound to that condition.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1020000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Amburukay: Sugidanon (Epics) of Panay Book II (Magos, Alicia P. et al.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1020000-0001-4001-8001-000000000002', ch_id, 'story', 'Raising the Daughters', 1, 'draft', 'Amburukay raises Matan-ayon and Saranggaon as her own daughters, keeping them in a golden chamber as binukot. She makes an extraordinary vow: her adopted daughters will marry whoever succeeds in stealing her golden pubic hair.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1020000-0001-4001-8001-000000000003', ch_id, 'story', 'The Hair and the Condition', 2, 'draft', 'When a string on Labaw Donggon''s musical instrument breaks, he learns that Amburukay''s hair can replace it. He enchants her into sleep and cuts the hair, only to discover that taking it has bound him to her condition. Believing he must marry the frightening hermit herself, he approaches the wedding reluctantly. Amburukay instead presents the daughters she has raised and judges Labaw Donggon worthy to marry them.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1020000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Golden Chamber', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1020000-0001-4001-8001-000000000005', ch_id, 'characters', 'Characters in This Chapter', 4, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
