      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1030000-0001-4001-8001-000000000001', 'Matan-ayon', 'Promised in marriage to Labaw Donggon before birth; a gold medallion marks the agreement; sought also by Sinagnayan.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1030000-0001-4001-8001-000000000001', 0 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1030000-0001-4001-8001-000000000001');
