      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1030000-0001-4001-8001-000000000001', ch_id, 'Promises and marriage conditions', 'PENDING CLIENT APPROVAL — The source describes a prior promise, a gold medallion, and recovery of an heirloom sailboat as a marriage condition.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1030000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Derikaryong Pada: Sugidanon (Epics) of Panay Book III (Magos, Alicia P.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1030000-0001-4001-8001-000000000002', ch_id, 'story', 'Promise Before Birth', 1, 'draft', 'Before Matan-ayon is born, she has already been promised in marriage to Labaw Donggon. A gold medallion is given as the sign of this agreement.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1030000-0001-4001-8001-000000000003', ch_id, 'story', 'A New Suitor and a Condition', 2, 'draft', 'When she reaches marriageable age, Sinagnayan also seeks her. He is connected to Paglambuhan, who has taken an heirloom sailboat belonging to Matan-ayon''s parents. The recovery of the vessel becomes the condition by which a suitor may prove his right to marry her. Labaw Donggon is caught between a prior promise and a new test. Marriage here is not simply private romance: it joins families, wealth, reputation, inherited objects, and promises made before the individuals concerned are old enough to act for themselves.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1030000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Gold Medallion', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1030000-0001-4001-8001-000000000005', ch_id, 'characters', 'Characters in This Chapter', 4, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
