      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1040000-0001-4001-8001-000000000001', ch_id, 'Mediation and authority', 'PENDING CLIENT APPROVAL — The source states that Laon Sina must intervene because victory cannot be secured through force alone.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1040000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Balanakon: Sugidanon (Epics) of Panay Book VII (Magos, Alicia P. & Ramirez, Anna Razel Limoso).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1040000-0001-4001-8001-000000000002', ch_id, 'story', 'The Challenge', 1, 'draft', 'Balanakon is a dalagangan, a person possessing extraordinary innate power. Taghuy persuades him to challenge Labaw Donggon and seek Matan-ayon. During his journey, Balanakon is stopped by Sarandihon, Labaw Donggon''s brother, but Sarandihon cannot defeat him.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1040000-0001-4001-8001-000000000003', ch_id, 'story', 'Intervention', 2, 'draft', 'Taghuy summons Labaw Donggon, yet even the brothers'' combined strength is insufficient. The conflict ends only when Laon Sina intervenes. Balanakon''s power is genuine, and victory cannot be secured through force alone; an authoritative intermediary must restore order before rivalry destroys the relationships surrounding the fighters.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1040000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Challenge', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
