      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1050000-0001-4001-8001-000000000008', 7 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1050000-0001-4001-8001-000000000008');
      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1050000-0001-4001-8001-000000000001', ch_id, 'Jurisdiction and mediation', 'PENDING CLIENT APPROVAL — The source describes multiple jurisdictions and Luyong Kabig mediating beyond Labaw Donggon''s territory.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1050000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Kalampay: Sugidanon (Epics) of Panay Book V (Magos, Alicia P. & Ramirez, Anna Razel Limoso).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1050000-0001-4001-8001-000000000002', ch_id, 'story', 'The Crab Island', 1, 'draft', 'Masangladon, a being of extraordinary power associated with the underworld, desires Matan-ayon. He transforms a kalampay, or crab, into an island covered with fruit trees. Matan-ayon is made to feel unbearably warm and goes to the island to bathe. As she gathers fruit, she is unknowingly carried toward the panibyungan, the source of waters descending into the underworld.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1050000-0001-4001-8001-000000000003', ch_id, 'story', 'Descent and Mediation', 2, 'draft', 'Taghuy informs Labaw Donggon. Labaw and Paubare attempt to descend after her, but the enormous crab blocks their way. Katnub Magkaruan dives beneath it and makes an opening in its joints through which Labaw Donggon can pass. Labaw Donggon cannot defeat Masangladon. Luyong Kabig, sister of Laon Sina and a judge in the underworld, must mediate an agreement permitting Matan-ayon to return. The resolution demonstrates that the epic world contains several jurisdictions and powers; even Labaw Donggon must submit to negotiation beyond his own territory.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1050000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Crab Island', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1050000-0001-4001-8001-000000000005', ch_id, 'characters', 'Characters in This Chapter', 4, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
