      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1060000-0001-4001-8001-000000000001', ch_id, 'Agency in conflict', 'PENDING CLIENT APPROVAL — The source states Matan-ayon transforms herself into a man to assist her brother rather than remaining a passive prize.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1060000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Pahagunong: Sugidanon (Epics) of Panay Book IV (Magos, Alicia P. & Ramirez, Anna Razel Limoso).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1060000-0001-4001-8001-000000000002', ch_id, 'story', 'Permission to Sail', 1, 'draft', 'Labaw Donggon asks his wives, Matan-ayon and Padilagong Bulan, for permission to sail. Matan-ayon agrees, while Padilagong Bulan insists on accompanying him. When he refuses, she gives him lime and betel quid prepared from the bones of a giant turtle. Eating it transforms him into a pawikan. Matan-ayon and her brother Paubare follow the transformed hero.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1060000-0001-4001-8001-000000000003', ch_id, 'story', 'Conflict and Restoration', 2, 'draft', 'Pahagunong sees Matan-ayon bathing, desires her, and defeats Paubare in combat. Matan-ayon does not remain a passive prize: she transforms herself into a man and enters the conflict to assist her brother. Laon Sina eventually restores Labaw Donggon and mediates the dispute.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1060000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Transformation', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
