      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1070000-0001-4001-8001-000000000004', 'Pinailog sa Pinggan', 'Sinagnayan''s wife and Matan-ayon''s sister; to be brought into Labaw Donggon''s household.', 'draft') ON CONFLICT (id) DO NOTHING;
