      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1070000-0001-4001-8001-000000000001', ch_id, 'Cooperation and secret knowledge', 'PENDING CLIENT APPROVAL — The source states strength alone accomplishes little without secret knowledge, disguise, and cooperation.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1070000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Sinagnayan: Sugidanon (Epics) of Panay Book VI (Magos, Alicia P. et al.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1070000-0001-4001-8001-000000000002', ch_id, 'story', 'The Confrontation Urged', 1, 'draft', 'Matan-ayon urges Labaw Donggon to confront Sinagnayan so that Pinailog sa Pinggan—Sinagnayan''s wife and Matan-ayon''s sister—can be brought into Labaw Donggon''s household. Before reaching Sinagnayan, Labaw Donggon fights Sarandihon without either man realizing they are brothers.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1070000-0001-4001-8001-000000000003', ch_id, 'story', 'Secret Knowledge and Victory', 2, 'draft', 'Laon Sina intervenes, reveals their relationship, and explains that Sinagnayan''s life-force is concealed in an eggshell inside the heart of a lion guarded by his mother, Minayunmon. Sarandihon transforms himself into Sinagnayan, uses a magical taghuy to put Minayunmon to sleep, kills the lion, and removes the eggshell. Labaw Donggon can then defeat Sinagnayan and bring Pinailog home. Strength alone accomplishes little without secret knowledge, disguise, and cooperation.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1070000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Concealed Life-Force', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1070000-0001-4001-8001-000000000005', ch_id, 'characters', 'Characters in This Chapter', 4, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
