      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1080000-0001-4001-8001-000000000001', 'Humadapnon', 'Searches for a suitable wife; courts Nagmalitong Yawa (Mali); central figure of the four-volume Humadapnon epic.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1080000-0001-4001-8001-000000000001', 0 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1080000-0001-4001-8001-000000000001');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1080000-0001-4001-8001-000000000002', 'Nagmalitong Yawa (Mali)', 'Courted by Humadapnon; disguises herself, performs ritual and magical actions, rescues Humadapnon, and makes strategic decisions.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1080000-0001-4001-8001-000000000002', 1 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1080000-0001-4001-8001-000000000002');
      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1080000-0001-4001-8001-000000000001', ch_id, 'Agency beyond courtship', 'PENDING CLIENT APPROVAL — The source describes Mali performing ritual actions, rescuing Humadapnon, and making strategic decisions beyond being the sought wife.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1080000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Humadapnon: Tarangban: Sugidanon (Epics) of Panay Book VIII, Volume 1 (Magos, Alicia P. et al.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1080000-0001-4001-8001-000000000002', ch_id, 'story', 'The Search and Courtship', 1, 'draft', 'Humadapnon is the longest title in the series and occupies four published volumes. Its narrative follows Humadapnon''s search for a suitable wife, his courtship of Nagmalitong Yawa—frequently called Mali—and the promises, rivalries, separations, and reconciliations that follow.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1080000-0001-4001-8001-000000000003', ch_id, 'story', 'Mali''s Role', 2, 'draft', 'Mali is not merely the woman Humadapnon seeks. Throughout these episodes she disguises herself, performs ritual and magical actions, rescues Humadapnon, helps him defeat opponents, makes strategic decisions, and answers humiliation and betrayal.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1080000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: Courtship and Rivalry', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1080000-0001-4001-8001-000000000005', ch_id, 'characters', 'Characters in This Chapter', 4, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
