      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1090000-0001-4001-8001-000000000001', 'Humadapnon', 'Must retrieve Mali''s tuos heirloom boat; fights Paglambuhan and Sumagulong; left in a golden basket.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1090000-0001-4001-8001-000000000001', 0 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1090000-0001-4001-8001-000000000001');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1090000-0001-4001-8001-000000000002', 'Nagmalitong Yawa (Mali)', 'Intervenes during the fight; becomes jealous; takes the boats and departs.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1090000-0001-4001-8001-000000000002', 1 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1090000-0001-4001-8001-000000000002');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1090000-0001-4001-8001-000000000003', 'Paglambuhan', 'Possesses the heirloom boat serving as Mali''s tuos.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1090000-0001-4001-8001-000000000003', 2 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1090000-0001-4001-8001-000000000003');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1090000-0001-4001-8001-000000000004', 'Sumagulong', 'Fights Humadapnon alongside Paglambuhan.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1090000-0001-4001-8001-000000000004', 3 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1090000-0001-4001-8001-000000000004');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1090000-0001-4001-8001-000000000005', 'Taghuy', 'Attempts to reconcile Humadapnon and Mali.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1090000-0001-4001-8001-000000000005', 4 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1090000-0001-4001-8001-000000000005');
      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1090000-0001-4001-8001-000000000001', ch_id, 'Custom and courtship tests', 'PENDING CLIENT APPROVAL — The source describes tuos, custom after defeat, and reframing confrontation as a test of strength.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1090000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Humadapnon: Pagbalukat ka Biday: Sugidanon (Epics) of Panay Book VIII, Volume 2 (Magos, Alicia P. et al.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1090000-0001-4001-8001-000000000002', ch_id, 'story', 'The Heirloom Boat', 1, 'draft', 'To continue his courtship, Humadapnon must retrieve the heirloom boat serving as Mali''s tuos, or mark of engagement. Paglambuhan possesses the vessel. Humadapnon fights Paglambuhan and Sumagulong but cannot defeat them unaided. Mali intervenes, distracting Paglambuhan so that Humadapnon can wound him.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1090000-0001-4001-8001-000000000003', ch_id, 'story', 'Jealousy and Departure', 2, 'draft', 'Custom then requires Humadapnon to stay with the defeated man''s wife. When he remains longer than expected, Mali becomes jealous. She takes both Humadapnon''s golden boat and the recovered heirloom vessel and departs, leaving him in a golden basket. Taghuy attempts to reconcile them. Humadapnon later challenges Mali''s father, but the confrontation is reframed as a test of the suitor''s strength.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1090000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Heirloom Boat', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1090000-0001-4001-8001-000000000005', ch_id, 'characters', 'Characters in This Chapter', 4, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
