      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1100000-0001-4001-8001-000000000001', ch_id, 'Marriage as social union', 'PENDING CLIENT APPROVAL — The source emphasizes hospitality, kinship, marriage, prestige, and the hungaw ceremony joining extended families.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1100000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Humadapnon: Hungaw: Sugidanon (Epics) of Panay Book VIII, Volume 3 (Magos, Alicia P. et al.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1100000-0001-4001-8001-000000000002', ch_id, 'story', 'Formal Courtship', 1, 'draft', 'After recovering the biday serving as Mali''s engagement token, Humadapnon formally seeks her hand. An initial misunderstanding arises with Labaw Donggon, but Humadapnon is welcomed by Mali''s relatives. Their marriage is arranged and attended by respected guests.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1100000-0001-4001-8001-000000000003', ch_id, 'story', 'The Hungaw Ceremony', 2, 'draft', 'The volume gives particular attention to the hungaw wedding ceremony and to hospitality, kinship, marriage, prestige, and the supernatural. It shows the social work needed to turn a courtship into a recognized union involving two extended families.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1100000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Hungaw Ceremony', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
