      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1110000-0001-4001-8001-000000000001', ch_id, 'Honour and violated tuos', 'PENDING CLIENT APPROVAL — The source describes ginlawan as public reckoning when a tuos has been violated, and separation despite resurrection.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1110000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Humadapnon: Ginlawan: Sugidanon (Epics) of Panay Book VIII, Volume 4 (Magos, Alicia P. et al.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1110000-0001-4001-8001-000000000002', ch_id, 'story', 'Plot and Feast', 1, 'draft', 'Humadapnon and Dumalapdap return to sea to find a suitable marriage match for Dumalapdap. During their absence, Taghoy plots with Paglambuhan and Sumagulong to take Mali from Humadapnon. Sumagulong persuades Mali''s relatives to accept the match, and a wedding feast begins.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1110000-0001-4001-8001-000000000003', ch_id, 'story', 'Death, Restoration, and Ginlawan', 2, 'draft', 'Humadapnon returns during the festivities, and the conflict leads to Mali''s death. Remorseful, he restores her to life and asks forgiveness from Mali and her parents. Resurrection does not erase the humiliation and resentment, however, and the couple separates. Ginlawan refers to a public punishment or reckoning imposed when a tuos has been violated. The volume places honour, loyalty, justice, and marital obligation above the expectation that a supernatural rescue must produce a happy ending.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1110000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: Ginlawan', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1110000-0001-4001-8001-000000000005', ch_id, 'characters', 'Characters in This Chapter', 4, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.section_characters (section_id, character_id, sort_order) SELECT 'a1110000-0001-4001-8001-000000000005', character_id, sort_order FROM public.chapter_characters WHERE chapter_id = ch_id ON CONFLICT DO NOTHING;
