      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1120000-0001-4001-8001-000000000002', 1 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1120000-0001-4001-8001-000000000002');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1120000-0001-4001-8001-000000000003', 'Laon Sina', 'Advises Humadapnon to plant an alayaw tree.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1120000-0001-4001-8001-000000000003', 2 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1120000-0001-4001-8001-000000000003');
      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1120000-0001-4001-8001-000000000001', ch_id, 'Boundary and intermediary', 'PENDING CLIENT APPROVAL — The source describes the alayaw tree crossing the boundary the suitor cannot cross.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1120000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Alayaw: Sugidanon (Epics) of Panay Book IX (Magos, Alicia P. et al.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1120000-0001-4001-8001-000000000002', ch_id, 'story', 'Seclusion and Desire', 1, 'draft', 'Humadapnon wants to see Mali, but she is secluded in her family''s burukutan. Laon Sina advises him to plant an alayaw tree in the yard of Mali''s parents. Its sweet-smelling flowers are expected to entice Mali to leave her enclosure and gather the blossoms, allowing Humadapnon to see the woman he hopes to court.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1120000-0001-4001-8001-000000000003', ch_id, 'story', 'The Fragrant Intermediary', 2, 'draft', 'The fragrant tree becomes an intermediary. It crosses the boundary that the suitor cannot cross and turns attraction into something carried through scent, curiosity, and the landscape surrounding the household.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1120000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: The Alayaw Tree', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
