      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1130000-0001-4001-8001-000000000001', 'Matan-ayon', 'Ill and extremely thin; wants Mali initiated into ritual knowledge for inheritance of powers and a spirit guide.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1130000-0001-4001-8001-000000000001', 0 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1130000-0001-4001-8001-000000000001');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1130000-0001-4001-8001-000000000002', 'Ginduluman', 'Summoned to conduct ceremonies required for Matan-ayon''s recovery.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1130000-0001-4001-8001-000000000002', 1 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1130000-0001-4001-8001-000000000002');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1130000-0001-4001-8001-000000000003', 'Nagmalitong Yawa (Mali)', 'Prevented from attending ceremony; answers through deception and magic; carried away in a golden basket.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1130000-0001-4001-8001-000000000003', 2 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1130000-0001-4001-8001-000000000003');
      INSERT INTO public.characters (id, name, description, review_status) VALUES ('b1130000-0001-4001-8001-000000000004', 'Humadapnon', 'Prevents Mali from attending the ceremony; courting another secluded woman.', 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_characters (chapter_id, character_id, sort_order) SELECT ch_id, 'b1130000-0001-4001-8001-000000000004', 3 WHERE NOT EXISTS (SELECT 1 FROM public.chapter_characters WHERE chapter_id = ch_id AND character_id = 'b1130000-0001-4001-8001-000000000004');
      INSERT INTO public.learning_points (id, chapter_id, title, description, sort_order, review_status) VALUES ('c1130000-0001-4001-8001-000000000001', ch_id, 'Ritual inheritance', 'PENDING CLIENT APPROVAL — The source connects Mali to women''s ritual inheritance and knowledge passed through her maternal family.', 0, 'draft') ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1130000-0001-4001-8001-000000000001', ch_id, 'introduction', 'Chapter Introduction', 0, 'draft', 'This chapter presents an educational summary adapted from the client-provided source document Nagbuhis: Sugidanon (Epics) of Panay Book X (Magos, Alicia P. et al.).
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1130000-0001-4001-8001-000000000002', ch_id, 'story', 'Illness and Ceremony', 1, 'draft', 'Matan-ayon has become ill and extremely thin. Ginduluman is summoned to conduct ceremonies required for her recovery. Matan-ayon also wants Mali initiated more fully into ritual knowledge so that Mali may inherit powers and a spirit guide. When the community goes to the seashore for the ceremony, Humadapnon prevents Mali from attending.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1130000-0001-4001-8001-000000000003', ch_id, 'story', 'Deception and Departure', 2, 'draft', 'She later discovers that he is courting another secluded woman. Mali answers through deception and magic. She creates or becomes associated with an enchanted pillow that takes her place, bids other men farewell, and deliberately arouses Humadapnon''s jealousy. With assistance from her grandmother in the upper world, Mali is carried away in a golden basket while the magical substitute continues the performance below. Humadapnon''s attempt to control Mali''s movement is answered by powers he cannot control. The episode also connects Mali to women''s ritual inheritance: she is not only a wife or desired binukot, but the prospective recipient of knowledge and authority passed through her maternal family.', NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1130000-0001-4001-8001-000000000004', ch_id, 'illustration', 'Illustration: Ritual at the Seashore', 3, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
      INSERT INTO public.chapter_sections (id, chapter_id, kind, title, sort_order, review_status, body_text, completion_message) VALUES ('a1130000-0001-4001-8001-000000000005', ch_id, 'characters', 'Characters in This Chapter', 4, 'draft', NULL, NULL) ON CONFLICT (id) DO NOTHING;
